    78  static void enqueue_goaway(h2o_http2_conn_t *conn, int errnum, h2o_iovec_t additional_data)
    79  {
    80      if (conn->state < H2O_HTTP2_CONN_STATE_IS_CLOSING) {
    81          /* http2 spec allows sending GOAWAY more than once (for one reason since errors may arise after sending the first one) */
    82          h2o_http2_encode_goaway_frame(&conn->_write.buf, conn->pull_stream_ids.max_open, errnum, additional_data);
    83          h2o_http2_conn_request_write(conn);
    84          conn->state = H2O_HTTP2_CONN_STATE_HALF_CLOSED;
    85      }
    86  }
