    88  static void graceful_shutdown_close_stragglers(h2o_timeout_entry_t *entry)
    89  {
    90      h2o_context_t *ctx = H2O_STRUCT_FROM_MEMBER(h2o_context_t, http2._graceful_shutdown_timeout, entry);
    91      h2o_linklist_t *node, *next;
    92
    93      /* We've sent two GOAWAY frames, close the remaining connections */
    94      for (node = ctx->http2._conns.next; node != &ctx->http2._conns; node = next) {
    95          h2o_http2_conn_t *conn = H2O_STRUCT_FROM_MEMBER(h2o_http2_conn_t, _conns, node);
    96          next = node->next;
    97          close_connection(conn);
    98      }
    99  }
