   101  static void graceful_shutdown_resend_goaway(h2o_timeout_entry_t *entry)
   102  {
   103      h2o_context_t *ctx = H2O_STRUCT_FROM_MEMBER(h2o_context_t, http2._graceful_shutdown_timeout, entry);
   104      h2o_linklist_t *node;
   105      int do_close_stragglers = 0;
   106
   107      for (node = ctx->http2._conns.next; node != &ctx->http2._conns; node = node->next) {
   108          h2o_http2_conn_t *conn = H2O_STRUCT_FROM_MEMBER(h2o_http2_conn_t, _conns, node);
   109          if (conn->state < H2O_HTTP2_CONN_STATE_HALF_CLOSED) {
   110              enqueue_goaway(conn, H2O_HTTP2_ERROR_NONE, (h2o_iovec_t){NULL});
   111              do_close_stragglers = 1;
   112          }
   113      }
   114
   115      /* After waiting a second, we still had active connections. If configured, wait one
   116       * final timeout before closing the connections */
   117      if (do_close_stragglers && ctx->globalconf->http2.graceful_shutdown_timeout) {
   118          ctx->http2._graceful_shutdown_timeout.cb = graceful_shutdown_close_stragglers;
   119          h2o_timeout_link(ctx->loop, &ctx->http2.graceful_shutdown_timeout, &ctx->http2._graceful_shutdown_timeout);
   120      }
   121  }
