   123  static void initiate_graceful_shutdown(h2o_context_t *ctx)
   124  {
   125      /* draft-16 6.8
   126       * A server that is attempting to gracefully shut down a connection SHOULD send an initial GOAWAY frame with the last stream
   127       * identifier set to 231-1 and a NO_ERROR code. This signals to the client that a shutdown is imminent and that no further
   128       * requests can be initiated. After waiting at least one round trip time, the server can send another GOAWAY frame with an
   129       * updated last stream identifier. This ensures that a connection can be cleanly shut down without losing requests.
   130       */
   131      h2o_linklist_t *node;
   132
   133      /* only doit once */
   134      if (ctx->http2._graceful_shutdown_timeout.cb != NULL)
   135          return;
   136      ctx->http2._graceful_shutdown_timeout.cb = graceful_shutdown_resend_goaway;
   137
   138      for (node = ctx->http2._conns.next; node != &ctx->http2._conns; node = node->next) {
   139          h2o_http2_conn_t *conn = H2O_STRUCT_FROM_MEMBER(h2o_http2_conn_t, _conns, node);
   140          if (conn->state < H2O_HTTP2_CONN_STATE_HALF_CLOSED) {
   141              h2o_http2_encode_goaway_frame(&conn->_write.buf, INT32_MAX, H2O_HTTP2_ERROR_NONE,
   142                                            (h2o_iovec_t){H2O_STRLIT("graceful shutdown")});
   143              h2o_http2_conn_request_write(conn);
   144          }
   145      }
   146      h2o_timeout_link(ctx->loop, &ctx->one_sec_timeout, &ctx->http2._graceful_shutdown_timeout);
   147  }
