   157  static void update_idle_timeout(h2o_http2_conn_t *conn)
   158  {
   159      h2o_timeout_unlink(&conn->_timeout_entry);
   160
   161      if (!conn->num_streams.response_blocked_by_server && !conn->num_streams.request_blocked_by_server &&
   162          conn->_write.buf_in_flight == NULL) {
   163          conn->_timeout_entry.cb = on_idle_timeout;
   164          h2o_timeout_link(conn->super.ctx->loop, &conn->super.ctx->http2.idle_timeout, &conn->_timeout_entry);
   165      }
   166  }
