   354  static void request_gathered_write(h2o_http2_conn_t *conn)
   355  {
   356      assert(conn->state < H2O_HTTP2_CONN_STATE_IS_CLOSING);
   357      if (conn->sock->_cb.write == NULL && !h2o_timeout_is_linked(&conn->_write.timeout_entry))
   358          h2o_timeout_link(conn->super.ctx->loop, &conn->super.ctx->zero_timeout, &conn->_write.timeout_entry);
