   361  static int update_stream_output_window(h2o_http2_stream_t *stream, ssize_t delta)
   362  {
   363      ssize_t cur = h2o_http2_window_get_window(&stream->output_window);
   364      if (h2o_http2_window_update(&stream->output_window, delta) != 0)
   365          return -1;
   366      if (cur <= 0 && h2o_http2_window_get_window(&stream->output_window) > 0 &&
   367          (h2o_http2_stream_has_pending_data(stream) || stream->state >= H2O_HTTP2_STREAM_STATE_SEND_BODY_IS_FINAL)) {
   368          assert(!h2o_linklist_is_linked(&stream->_refs.link));
   369          h2o_http2_scheduler_activate(&stream->_refs.scheduler);
   370      }
   371      return 0;
   372  }
