   374  static int handle_incoming_request(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream, const uint8_t *src, size_t len,
   375                                     const char **err_desc)
   376  {
   377      int ret, header_exists_map;
   378
   379      assert(stream->state == H2O_HTTP2_STREAM_STATE_RECV_HEADERS);
   380
   381      header_exists_map = 0;
   382      if ((ret = h2o_hpack_parse_headers(&stream->req, &conn->_input_header_table, src, len, &header_exists_map,
   383                                         &stream->req.content_length, &stream->cache_digests, err_desc)) != 0) {
   384          if (ret == H2O_HTTP2_ERROR_INVALID_HEADER_CHAR) {
   385              /* fast forward the stream's state so that we can start sending the response */
   386              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   387              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_SEND_HEADERS);
   388              h2o_send_error_400(&stream->req, "Invalid Headers", *err_desc, 0);
   389              return 0;
   390          }
   391          return ret;
   392      }
   393
   394  #define EXPECTED_MAP                                                                                                               \
   395      (H2O_HPACK_PARSE_HEADERS_METHOD_EXISTS | H2O_HPACK_PARSE_HEADERS_PATH_EXISTS | H2O_HPACK_PARSE_HEADERS_SCHEME_EXISTS)
   396      if ((header_exists_map & EXPECTED_MAP) != EXPECTED_MAP) {
   397          ret = H2O_HTTP2_ERROR_PROTOCOL;
   398          goto SendRSTStream;
   399      }
   400  #undef EXPECTED_MAP
   401
   402      /* handle the request */
   403      if (conn->num_streams.pull.open > H2O_HTTP2_SETTINGS_HOST.max_concurrent_streams) {
   404          ret = H2O_HTTP2_ERROR_REFUSED_STREAM;
   405          goto SendRSTStream;
   406      }
   407
   408      if (stream->_req_body.body == NULL) {
   409          execute_or_enqueue_request(conn, stream);
   410      } else {
   411          h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_RECV_BODY);
   412      }
   413      return 0;
   414
   415  SendRSTStream:
   416      stream_send_error(conn, stream->stream_id, ret);
   417      h2o_http2_stream_reset(conn, stream);
   418      return 0;
   419  }
