   557  static int write_req_chunk(void *req_, h2o_iovec_t payload, int is_end_stream)
   558  {
   559      h2o_req_t *req = req_;
   560      h2o_http2_stream_t *stream = H2O_STRUCT_FROM_MEMBER(h2o_http2_stream_t, req, req);
   561      h2o_http2_conn_t *conn = (h2o_http2_conn_t *)stream->req.conn;
   562
   563      if (h2o_buffer_append(&stream->_req_body.body, payload.base, payload.len) == 0)
   564          return -1;
   565      stream->req.entity = h2o_iovec_init(stream->_req_body.body->bytes, stream->_req_body.body->size);
   566
   567      /* handle request if request body is complete */
   568      if (!stream->req._write_req_chunk_done) {
   569          if (is_end_stream) {
   570              stream->req.entity = h2o_iovec_init(stream->_req_body.body->bytes, stream->_req_body.body->size);
   571              execute_or_enqueue_request(conn, stream);
   572          } else {
   573              if (!stream->req._found_handler) {
   574                  stream->req._found_handler = 1;
   575                  h2o_handler_t *h = h2o_get_first_handler(&stream->req);
   576                  if (h != NULL && h->has_body_stream) {
   577                      stream->req._write_req_chunk_done = write_req_chunk_done;
   578                      stream->_req_body.streamed_body_size = stream->_req_body.body->size;
   579                      execute_or_enqueue_request(conn, stream);
   580                  }
   581              } else {
   582                  write_req_chunk_done(req, payload.len, is_end_stream);
   583              }
   584          }
   585      } else {
   586          if (is_end_stream) {
   587              stream->req._write_req_chunk_done = NULL;
   588              stream->req._write_req_chunk.cb = NULL;
   589          }
   590      }
   591
   592      return 0;
   593  }
