   656  static int handle_headers_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
   657  {
   658      h2o_http2_headers_payload_t payload;
   659      h2o_http2_stream_t *stream;
   660      int ret;
   661
   662      /* decode */
   663      if ((ret = h2o_http2_decode_headers_payload(&payload, frame, err_desc)) != 0)
   664          return ret;
   665      if ((frame->stream_id & 1) == 0) {
   666          *err_desc = "invalid stream id in HEADERS frame";
   667          return H2O_HTTP2_ERROR_PROTOCOL;
   668      }
   669      if (!(conn->pull_stream_ids.max_open < frame->stream_id)) {
   670          if ((stream = h2o_http2_conn_get_stream(conn, frame->stream_id)) != NULL &&
   671              stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY) {
   672              /* is a trailer */
   673              if ((frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) == 0) {
   674                  *err_desc = "trailing HEADERS frame MUST have END_STREAM flag set";
   675                  return H2O_HTTP2_ERROR_PROTOCOL;
   676              }
   677              stream->req.entity = h2o_iovec_init(stream->_req_body.body->bytes, stream->_req_body.body->size);
   678              if ((frame->flags & H2O_HTTP2_FRAME_FLAG_END_HEADERS) == 0)
   679                  goto PREPARE_FOR_CONTINUATION;
   680              return handle_trailing_headers(conn, stream, payload.headers, payload.headers_len, err_desc);
   681          } else if (!stream || stream->state != H2O_HTTP2_STREAM_STATE_IDLE) {
   682              /* it's legit that stream exists and is IDLE if a PRIORITY frame was received earlier */
   683              *err_desc = "invalid stream id in HEADERS frame";
   684              return H2O_HTTP2_ERROR_STREAM_CLOSED;
   685          }
   686      }
   687      if (frame->stream_id == payload.priority.dependency) {
   688          *err_desc = "stream cannot depend on itself";
   689          return H2O_HTTP2_ERROR_PROTOCOL;
   690      }
   691
   692      if (conn->state >= H2O_HTTP2_CONN_STATE_HALF_CLOSED)
   693          return 0;
   694
   695      /* open or determine the stream and prepare */
   696      if ((stream = h2o_http2_conn_get_stream(conn, frame->stream_id)) != NULL) {
   697          if ((frame->flags & H2O_HTTP2_FRAME_FLAG_PRIORITY) != 0) {
   698              set_priority(conn, stream, &payload.priority, 1);
   699              stream->received_priority = payload.priority;
   700          }
   701      } else {
   702          stream = h2o_http2_stream_open(conn, frame->stream_id, NULL, &payload.priority);
   703          set_priority(conn, stream, &payload.priority, 0);
   704      }
   705      h2o_http2_stream_prepare_for_request(conn, stream);
   706      stream->req._write_req_chunk.cb = write_req_chunk;
   707      stream->req._write_req_chunk.priv = &stream->req;
   708
   709      /* setup container for request body if it is expected to arrive */
   710      if ((frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) == 0)
   711          h2o_buffer_init(&stream->_req_body.body, &h2o_socket_buffer_prototype);
   712
   713      if ((frame->flags & H2O_HTTP2_FRAME_FLAG_END_HEADERS) != 0) {
   714          /* request is complete, handle it */
   715          return handle_incoming_request(conn, stream, payload.headers, payload.headers_len, err_desc);
   716      }
   717
   718  PREPARE_FOR_CONTINUATION:
   719      /* request is not complete, store in buffer */
   720      conn->_read_expect = expect_continuation_of_headers;
   721      h2o_buffer_init(&conn->_headers_unparsed, &h2o_socket_buffer_prototype);
   722      h2o_buffer_reserve(&conn->_headers_unparsed, payload.headers_len);
   723      memcpy(conn->_headers_unparsed->bytes, payload.headers, payload.headers_len);
   724      conn->_headers_unparsed->size = payload.headers_len;
   725      return 0;
   726  }
