   728  static int handle_priority_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
   729  {
   730      h2o_http2_priority_t payload;
   731      h2o_http2_stream_t *stream;
   732      int ret;
   733
   734      if ((ret = h2o_http2_decode_priority_payload(&payload, frame, err_desc)) != 0)
   735          return ret;
   736      if (frame->stream_id == payload.dependency) {
   737          *err_desc = "stream cannot depend on itself";
   738          return H2O_HTTP2_ERROR_PROTOCOL;
   739      }
   740
   741      if ((stream = h2o_http2_conn_get_stream(conn, frame->stream_id)) != NULL) {
   742          stream->received_priority = payload;
   743          /* ignore priority changes to pushed streams with weight=257, since that is where we are trying to be smarter than the web
   744           * browsers
   745           */
   746          if (h2o_http2_scheduler_get_weight(&stream->_refs.scheduler) != 257)
   747              set_priority(conn, stream, &payload, 1);
   748      } else {
   749          if (h2o_http2_stream_is_push(frame->stream_id)) {
   750              /* Ignore PRIORITY frames for closed or idle pushed streams */
   751              return 0;
   752          } else {
   753              /* Ignore PRIORITY frames for closed pull streams */
   754              if (frame->stream_id <= conn->pull_stream_ids.max_open)
   755                  return 0;
   756          }
   757          if (conn->num_streams.priority.open >= conn->super.ctx->globalconf->http2.max_streams_for_priority) {
   758              *err_desc = "too many streams in idle/closed state";
   759              /* RFC 7540 10.5: An endpoint MAY treat activity that is suspicious as a connection error (Section 5.4.1) of type
   760               * ENHANCE_YOUR_CALM.
   360          if (state != H2O_SEND_STATE_IN_PROGRESS) {
   361              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_SEND_BODY_IS_FINAL);
   362          }
   363          break;
   364      case H2O_HTTP2_STREAM_STATE_END_STREAM:
   365          /* might get set by h2o_http2_stream_reset */
   366          return;
   367      default:
   368          assert(!"cannot be in a receiving state");
   369      }
   370
   371      /* save the contents in queue */
   372      if (bufcnt != 0) {
   373          h2o_vector_reserve(&req->pool, &stream->_data, bufcnt);
   374          memcpy(stream->_data.entries, bufs, sizeof(h2o_iovec_t) * bufcnt);
   375          stream->_data.size = bufcnt;
   376      }
   377
   378      h2o_http2_conn_register_for_proceed_callback(conn, stream);
   379  }
