   413  void h2o_http2_stream_proceed(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
   414  {
   415      if (stream->state == H2O_HTTP2_STREAM_STATE_END_STREAM) {
   416          h2o_http2_stream_close(conn, stream);
   417      } else {
   418          if (!conn->num_streams.response_blocked_by_server)
   419              h2o_http2_stream_set_response_blocked_by_server(conn, stream, 1);
   420          h2o_proceed_response(&stream->req);
   421      }
   422  }
